# Perform BFS from node b3e3e393c7 to find nodes at exactly depth 8
from collections import deque

start_node = 'b3e3e393c7'
target_depth = 8

# BFS: track (node, depth)
queue = deque([(start_node, 0)])
visited = {start_node}
nodes_at_depth_8 = []

while queue:
    current_node, current_depth = queue.popleft()

    # If we've reached depth 8, add to results
    if current_depth == target_depth:
        nodes_at_depth_8.append(current_node)
        continue  # Don't explore further from depth 8

    # Explore neighbors
    if current_node in graph:
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, current_depth + 1))

print(f"Nodes at exactly depth 8: {sorted(nodes_at_depth_8)}")
print(f"Number of nodes at depth 8: {len(nodes_at_depth_8)}")

# Let's also verify by checking depths
print(f"\nVerification - checking some paths:")
def find_path_to_node(target, start=start_node):
    """Find shortest path from start to target"""
    queue = deque([(start, [start])])
    visited = {start}
    while queue:
        current, path = queue.popleft()
        if current == target:
            return path
        if current in graph:
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))
    return None

for node in nodes_at_depth_8[:3]:
    path = find_path_to_node(node)
    print(f"Path to {node}: depth {len(path)-1}, path: {path}")
